import type { Article } from "../curriculumTypes";

export const ARTICLES: Article[] = [{"id":"art_xb3_01","moduleId":"MODULE_XB_3","title":"氓","subtitle":null,"author":"诗经","dynasty":"先秦","genre":"诗","isGaoKao72":false,"recitationScope":"非课标必背","fullContent":"氓之蚩蚩，抱布贸丝。匪来贸丝，来即我谋。送子涉淇，至于顿丘。匪我愆期，子无良媒。将子无怒，秋以为期。\n乘彼垝垣，以望复关。不见复关，泣涕涟涟。既见复关，载笑载言。尔卜尔筮，体无咎言。以尔车来，以我贿迁。\n桑之未落，其叶沃若。于嗟鸠兮，无食桑葚！于嗟女兮，无与士耽！士之耽兮，犹可说也。女之耽兮，不可说也。\n桑之落矣，其黄而陨。自我徂尔，三岁食贫。淇水汤汤，渐车帷裳。女也不爽，士贰其行。士也罔极，二三其德。\n三岁为妇，靡室劳矣；夙兴夜寐，靡有朝矣。言既遂矣，至于暴矣。兄弟不知，咥其笑矣。静言思之，躬自悼矣。\n及尔偕老，老使我怨。淇则有岸，隰则有泮。总角之宴，言笑晏晏。信誓旦旦，不思其反。反是不思，亦已焉哉！","paragraphs":["桑之未落，其叶沃若。于嗟女兮，无与士耽！士之耽兮，犹可说也；女之耽兮，不可说也。","信誓旦旦，不思其反。反是不思，亦已焉哉！"],"translation":"那个老实诚恳的小伙子，抱着布匹来换丝。","annotations":["总角之宴：少年时期相处的欢聚快乐。","信誓旦旦：誓言诚恳确凿。"],"sortOrder":1,"totalSegments":8,"totalCards":8},{"id":"art_xb3_02","moduleId":"MODULE_XB_3","title":"离骚(节选)","subtitle":"节选","author":"屈原","dynasty":"战国·楚","genre":"辞赋","isGaoKao72":true,"recitationScope":"节选（帝高阳之苗裔兮……来吾道夫先路）","fullContent":"帝高阳之苗裔兮，朕皇考曰伯庸。摄提贞于孟陬兮，惟庚寅吾以降。皇览揆余初度兮，肇锡余以嘉名：名余曰正则兮，字余曰灵均。\n纷吾既有此内美兮，又重之以修能。扈江离与辟芷兮，纫秋兰以为佩。汩余若将不及兮，恐年岁之不吾与。朝搴阰之木兰兮，夕揽洲之宿莽。日月忽其不淹兮，春与秋其代序。唯草木之零落兮，恐美人之迟暮。不抚壮而弃秽兮，何不改乎此度？乘骐骥以驰骋兮，来吾道夫先路！","paragraphs":["纷吾既有此内美兮，又重之以修能。扈江离与辟芷兮，纫秋兰以为佩。","日月忽其不淹兮，春与秋其代序。唯草木之零落兮，恐美人之迟暮。"],"translation":"我是古帝高阳氏的后裔，父亲字伯庸。","annotations":["香草美人：象征高尚德行与所忠君王。"],"sortOrder":2,"totalSegments":4,"totalCards":4},{"id":"art_xb3_03","moduleId":"MODULE_XB_3","title":"孔雀东南飞并序","subtitle":"并序","author":"汉乐府","dynasty":"汉代","genre":"乐府","isGaoKao72":false,"recitationScope":"非课标必背","fullContent":"孔雀东南飞，五里一徘徊。\n“十三能织素，十四学裁衣，十五弹箜篌，十六诵诗书。十七为君妇，心中常苦悲。君既为府吏，守节情不移，贱妾留空房，相见常日稀。鸡鸣入机织，夜夜不得息。三日断五匹，大人故嫌迟。非为织作迟，君家妇难为！妾不堪吏人妇，岂合令郎居？及时相遣归，炼得迎新妇。”\n府吏默无声，再拜还入户，举言谓新妇，哽咽不能语：“我自不驱卿，逼迫有阿母。卿但暂还家，吾今且报府。不久当归还，还必相迎取。以此下心意，慎勿违我言。”\n新妇谓府吏：“感君区区怀！君既若见录，不久望君来。君当作磐石，妾当作蒲苇，蒲苇纫如丝，磐石无转移。我有亲父兄，性行暴如雷，恐不任我意，逆以煎我怀。”举手长劳劳，二情同依依。\n两家求合葬，合葬华山傍。东西植松柏，左右种梧桐。枝枝相覆盖，叶叶相交通。中有双飞鸟，自名为鸳鸯，仰头相向鸣，夜夜达五更。行人驻足听，寡妇起彷徨。多谢后世人，戒之慎勿忘！","paragraphs":["君当作磐石，妾当作蒲苇，蒲苇纫如丝，磐石无转移。","东西植松柏，左右种梧桐。枝枝相覆盖，叶叶相交通。中有双飞鸟，自名为鸳鸯。"],"translation":"孔雀向着东南飞去，每飞五里就留恋徘徊。","annotations":["蒲苇纫如丝磐石无转移：形容爱情坚定忠贞不渝。"],"sortOrder":3,"totalSegments":10,"totalCards":10},{"id":"art_xb3_04","moduleId":"MODULE_XB_3","title":"蜀道难","subtitle":null,"author":"李白","dynasty":"唐代","genre":"乐府","isGaoKao72":true,"recitationScope":"FULL_TEXT","fullContent":"噫吁嚱，危乎高哉！蜀道之难，难于上青天！蚕丛及鱼凫，开国何茫然！尔来四万八千岁，始与秦塞通人烟。西当太白有鸟道，可以横绝峨眉巅。地崩山摧壮士死，然后天梯石栈相钩连。\n上有六龙回日之高标，下有冲波逆折之回川。黄鹤之飞尚不得过，猿猱欲度愁攀援。青泥何盘盘，百步九折萦岩峦。扪参历井仰胁息，以手抚膺坐长叹。\n问君西游何时还？畏途巉岩不可攀。但见悲鸟号古木，雄飞雌从绕林间。又闻子规啼夜月，愁空山。蜀道之难，难于上青天，使人听此凋朱颜！连峰去天不盈尺，枯松倒挂倚绝壁。飞湍瀑流争喧豗，砯崖转石万壑雷。其险也如此，嗟尔远道之人胡为乎来哉！\n剑阁峥嵘而崔嵬，一夫当关，万夫莫开。所守或匪亲，化为狼与豺。朝避猛虎，夕避长蛇；磨牙吮血，杀人如麻。锦城虽云乐，不如早还家。蜀道之难，难于上青天，侧身西望长咨嗟！","paragraphs":["噫吁嚱，危乎高哉！蜀道之难，难于上青天！","上有六龙回日之高标，下有冲波逆折之回川。黄鹤之飞尚不得过，猿猱欲度愁攀援。","连峰去天不盈尺，枯松倒挂倚绝壁。飞湍瀑流争喧豗，砯崖转石万壑雷。","剑阁峥嵘而崔嵬，一夫当关，万夫莫开。"],"translation":"哎呀呀，多么危险多么高峻！蜀道走起来真难，比登上青天还难。","annotations":["扪参历井：形容山势极高，伸手可摸星宿。","一夫当关万夫莫开：形容关隘极其险要。"],"sortOrder":4,"totalSegments":8,"totalCards":8},{"id":"art_xb3_05","moduleId":"MODULE_XB_3","title":"蜀相","subtitle":null,"author":"杜甫","dynasty":"唐代","genre":"诗","isGaoKao72":true,"recitationScope":"FULL_TEXT","fullContent":"丞相祠堂何处寻？锦官城外柏森森。映阶碧草自春色，隔叶黄鹂空好音。\n三顾频烦天下计，两朝开济老臣心。出师未捷身先死，长使英雄泪满襟。","paragraphs":["丞相祠堂何处寻？锦官城外柏森森。映阶碧草自春色，隔叶黄鹂空好音。","三顾频烦天下计，两朝开济老臣心。出师未捷身先死，长使英雄泪满襟。"],"translation":"何处去寻觅诸葛丞相的祠堂？锦官城外那绿柏茂密葱郁之处。","annotations":["三顾频烦：刘备三顾茅庐。","出师未捷身先死：颂诸葛亮至死不渝。"],"sortOrder":5,"totalSegments":4,"totalCards":4},{"id":"art_xb3_06","moduleId":"MODULE_XB_3","title":"望海潮·东南形胜","subtitle":null,"author":"柳永","dynasty":"宋代","genre":"词","isGaoKao72":true,"recitationScope":"FULL_TEXT","fullContent":"东南形胜，三吴都会，钱塘自古繁华。烟柳画桥，风帘翠幕，参差十万人家。云树绕堤沙，怒涛卷霜雪，天堑无涯。市列珠玑，户盈罗绮，竞豪奢。\n重湖叠巘清嘉，有三秋桂子，十里荷花。羌管弄晴，菱歌泛夜，嬉嬉钓叟莲娃。千骑拥高牙，乘醉听箫鼓，吟赏烟霞。异日图将好景，归去凤池夸。","paragraphs":["东南形胜，三吴都会，钱塘自古繁华。烟柳画桥，风帘翠幕，参差十万人家。","重湖叠巘清嘉，有三秋桂子，十里荷花。羌管弄晴，菱歌泛夜，嬉嬉钓叟莲娃。"],"translation":"东南重镇地理优胜，三吴首府，钱塘杭州自古繁华热闹。","annotations":["三秋桂子十里荷花：极写杭州秋日春水胜景。"],"sortOrder":6,"totalSegments":4,"totalCards":4},{"id":"art_xb3_07","moduleId":"MODULE_XB_3","title":"扬州慢·淮左名都","subtitle":null,"author":"姜夔","dynasty":"宋代","genre":"词","isGaoKao72":true,"recitationScope":"FULL_TEXT","fullContent":"淮左名都，竹西佳处，解鞍少驻初程。过春风十里，尽荠麦青青。自胡马窥江去后，废池乔木，犹厌言兵。渐黄昏，清角吹寒，都在空城。\n杜郎俊赏，算而今重到须惊。纵豆蔻词工，青楼梦好，难赋深情。二十四桥仍在，波心荡、冷月无声。念桥边红药，年年知为谁生？","paragraphs":["过春风十里，尽荠麦青青。自胡马窥江去后，废池乔木，犹厌言兵。","二十四桥仍在，波心荡、冷月无声。念桥边红药，年年知为谁生？"],"translation":"淮南东路著名的都会，竹西亭风景优美的地方。","annotations":["二十四桥仍在波心荡冷月无声：形容物是人非冷清荒凉。"],"sortOrder":7,"totalSegments":4,"totalCards":4},{"id":"art_xb3_08","moduleId":"MODULE_XB_3","title":"陈情表","subtitle":null,"author":"李密","dynasty":"西晋","genre":"散文","isGaoKao72":true,"recitationScope":"FULL_TEXT","fullContent":"臣密言：臣以险衅，夙遭闵凶。生孩六月，慈父见背；行年四岁，舅夺母志。祖母刘愍臣孤弱，躬亲抚养。臣少多疾病，九岁不行，零丁孤苦，至于成立。既无伯叔，终鲜兄弟，门衰祚薄，晚有儿息。外无期功强近之亲，内无应门五尺之僮，茕茕孑立，形影相吊。而刘夙婴疾病，常在床蓐，臣侍汤药，未曾废离\n臣密今年四十有四，祖母今年九十有六，是臣尽节于陛下之日长，报养刘之日短也。乌鸟私情，愿乞终养。","paragraphs":["茕茕孑立，形影相吊。而刘夙婴疾病，常在床蓐，臣侍汤药，未曾废离。","臣生当陨首，死当结草。乌鸟私情，愿乞终养。"],"translation":"臣李密陈述：臣因命运坎坷，幼年就遭遇深重不幸。","annotations":["茕茕孑立形影相吊：形容孤单无依。","乌鸟私情：幼鸟反哺报恩之情。"],"sortOrder":8,"totalSegments":6,"totalCards":6},{"id":"art_xb3_09","moduleId":"MODULE_XB_3","title":"项脊轩志","subtitle":null,"author":"归有光","dynasty":"明代","genre":"散文","isGaoKao72":true,"recitationScope":"第1段（项脊轩修葺与庭中夜景）","fullContent":"项脊轩，旧南阁子也。室仅方丈，可容一人居。百年老屋，尘泥渗漉，雨泽下注；每移案，顾视无可置者。又北向，不能得日，日过午已昏。余稍为修葺，使不上漏。前辟四窗，垣墙周庭，以当南日，日影反照，室始洞然。又杂植兰桂竹木于庭，旧时栏楯，亦遂增胜。借书满架，偃仰啸歌，冥然兀坐，万籁有声；而庭阶寂寂，小鸟时来啄食，人至不去。三五之夜，明月半墙，桂影斑驳，风移影动，珊珊可爱。","paragraphs":["项脊轩，旧南阁子也。室仅方丈，可容一人居。百年老屋，尘泥渗漉，雨泽下注；每移案，顾视无可置者。又北向，不能得日，日过午已昏。余稍为修葺，使不上漏。前辟四窗，垣墙周庭，以当南日，日影反照，室始洞然。又杂植兰桂竹木于庭，旧时栏楯，亦遂增胜。借书满架，偃仰啸歌，冥然兀坐，万籁有声；而庭阶寂寂，小鸟时来啄食，人至不去。三五之夜，明月半墙，桂影斑驳，风移影动，珊珊可爱。"],"translation":"项脊轩，就是原来的南阁子。","annotations":["三五之夜：农历十五月圆之夜。","亭亭如盖：枝叶舒展茂密如车盖。"],"sortOrder":9,"totalSegments":4,"totalCards":4},{"id":"art_xb3_10","moduleId":"MODULE_XB_3","title":"兰亭集序","subtitle":null,"author":"王羲之","dynasty":"东晋","genre":"散文","isGaoKao72":true,"recitationScope":"第1、3、4段（兰亭雅集、人生感慨、死生之叹）","fullContent":"永和九年，岁在癸丑，暮春之初，会于会稽山阴之兰亭，修禊事也。群贤毕至，少长咸集。此地有崇山峻岭，茂林修竹，又有清流急湍，映带左右，引以为流觞曲水，列坐其次。虽无丝竹管弦之盛，一觞一咏，亦足以畅叙幽情。\n夫人之相与，俯仰一世。或取诸怀抱，悟言一室之内；或因寄所托，放浪形骸之外。虽趣舍万殊，静躁不同，当其欣于所遇，暂得于己，快然自足，不知老之将至；及其所之既倦，情随事迁，感慨系之矣。向之所欣，俯仰之间，已为陈迹，犹不能不以之兴怀，况修短随化，终期于尽！古人云：“死生亦大矣”，岂不痛哉！\n每览昔人兴感之由，若合一契，未尝不临文嗟悼，不能喻之于怀。固知一死生为虚诞，齐彭殇为妄作。后之视今，亦犹今之视昔，悲夫！故列叙时人，录其所述，虽世殊事异，所以兴怀，其致一也。后之览者，亦将有感于斯文。","paragraphs":["永和九年，岁在癸丑，暮春之初，会于会稽山阴之兰亭，修禊事也。群贤毕至，少长咸集。此地有崇山峻岭，茂林修竹，又有清流急湍，映带左右，引以为流觞曲水，列坐其次。虽无丝竹管弦之盛，一觞一咏，亦足以畅叙幽情。","夫人之相与，俯仰一世。或取诸怀抱，悟言一室之内；或因寄所托，放浪形骸之外。虽趣舍万殊，静躁不同，当其欣于所遇，暂得于己，快然自足，不知老之将至；及其所之既倦，情随事迁，感慨系之矣。向之所欣，俯仰之间，已为陈迹，犹不能不以之兴怀，况修短随化，终期于尽！古人云：“死生亦大矣”，岂不痛哉！","每览昔人兴感之由，若合一契，未尝不临文嗟悼，不能喻之于怀。固知一死生为虚诞，齐彭殇为妄作。后之视今，亦犹今之视昔，悲夫！故列叙时人，录其所述，虽世殊事异，所以兴怀，其致一也。后之览者，亦将有感于斯文。"],"translation":"永和九年，岁次癸丑，暮春三月初，在会稽山阴的兰亭聚会。","annotations":["群贤毕至少长咸集：天下贤能之士与长幼皆聚。","一死生齐彭殇：视死生彭祖短折为一，斥其虚妄。"],"sortOrder":10,"totalSegments":8,"totalCards":8},{"id":"art_xb3_11","moduleId":"MODULE_XB_3","title":"归去来兮辞并序","subtitle":"并序","author":"陶渊明","dynasty":"东晋","genre":"辞赋","isGaoKao72":true,"recitationScope":"第1、2、4段（归田之志、到家之乐、乐天知命）","fullContent":"归去来兮，田园将芜胡不归？既自以心为形役，奚惆怅而独悲？悟已往之不谏，知来者之可追。实迷途其未远，觉今是而昨非。舟遥遥以轻飏，风飘飘而吹衣。问征夫以前路，恨晨光之熹微。\n乃瞻衡宇，载欣载奔。僮仆欢迎，稚子候门。三径就荒，松菊犹存。携幼入室，有酒盈樽。引壶觞以自酌，眄庭柯以怡颜。倚南窗以寄傲，审容膝之易安。园日涉以成趣，门虽设而常关。策扶老以流憩，时矫首而遐观。云无心以出岫，鸟倦飞而知还。景翳翳以将入，抚孤松而盘桓。\n已矣乎！寓形宇内复几时？曷不委心任去留？何为遑遑欲何之？富贵非吾愿，帝乡不可期。怀良辰以孤往，或植杖而耘耔。登东皋以舒啸，临清流而赋诗。聊乘化以归尽，乐夫天命复奚疑！","paragraphs":["归去来兮，田园将芜胡不归？既自以心为形役，奚惆怅而独悲？悟已往之不谏，知来者之可追。实迷途其未远，觉今是而昨非。舟遥遥以轻飏，风飘飘而吹衣。问征夫以前路，恨晨光之熹微。","乃瞻衡宇，载欣载奔。僮仆欢迎，稚子候门。三径就荒，松菊犹存。携幼入室，有酒盈樽。引壶觞以自酌，眄庭柯以怡颜。倚南窗以寄傲，审容膝之易安。园日涉以成趣，门虽设而常关。策扶老以流憩，时矫首而遐观。云无心以出岫，鸟倦飞而知还。景翳翳以将入，抚孤松而盘桓。","已矣乎！寓形宇内复几时？曷不委心任去留？何为遑遑欲何之？富贵非吾愿，帝乡不可期。怀良辰以孤往，或植杖而耘耔。登东皋以舒啸，临清流而赋诗。聊乘化以归尽，乐夫天命复奚疑！"],"translation":"回去吧！田园快要荒芜了，为什么还不回去呢？。","annotations":["觉今是而昨非：省悟如今正确而过去错误。","云无心以出岫：白云自然出山，寓任性自然。"],"sortOrder":11,"totalSegments":8,"totalCards":8},{"id":"art_xb3_12","moduleId":"MODULE_XB_3","title":"种树郭橐驼传","subtitle":null,"author":"柳宗元","dynasty":"唐代","genre":"散文","isGaoKao72":true,"recitationScope":"FULL_TEXT","fullContent":"郭橐驼，不知始何名。病偻，隆然伏行，有类橐驼者，故乡人号之“驼”。驼闻之，曰：“甚善。名我固当。”因舍其名，亦自谓橐驼云。其乡曰丰乐乡，在长安西。驼业种树，凡长安豪富人为观游及卖果者，皆争迎取养。视驼所种树，或移徙，无不活，且硕茂，早实以蕃。他植者虽窥伺效慕，莫能如也。\n有问之，对曰：“橐驼非能使木寿且孳也，能顺木之天，以致其性焉尔。凡植木之性，其本欲舒，其培欲平，其土欲故，其筑欲密。既然已，勿动勿虑，去不复顾。其莳也若子，其置也若弃，则其天者全而其性得矣。故吾不害其长而已，非有能硕茂之也；不抑耗其实而已，非有能早而蕃之也。他植者则不然，根拳而土易，其培之也，若不过焉则不及。苟有能反是者，则又爱之太恩，忧之太勤，旦视而暮抚，已去而复顾，甚者爪其肤以验其生枯，摇其本以观其疏密，而木之性日以离矣。虽曰爱之，其实害之；虽曰忧之，其实仇之，故不我若也。吾又何能为哉！”","paragraphs":["郭橐驼，不知始何名。病偻，隆然伏行，有类橐驼者，故乡人号之“驼”。驼闻之，曰：“甚善。名我固当。”因舍其名，亦自谓橐驼云。","驼业种树，凡长安豪富人为观游及卖果者，皆争迎取养。视驼所种树，或移徙，无不活，且硕茂，早实以蕃。他植者虽窥伺效慕，莫能如也。","橐驼非能使木寿且孳也，能顺木之天，以致其性焉尔。凡植木之性，其本欲舒，其培欲平，其土欲故，其筑欲密。既然已，勿动勿虑，去不复顾。其莳也若子，其置也若弃，则其天者全而其性得矣。","故吾不害其长而已，非有能硕茂之也；不抑耗其实而已，非有能早而蕃之也。他植者则不然，根拳而土易，其培之也，若不过焉则不及。","苟有能反是者，则又爱之太恩，忧之太勤，旦视而暮抚，已去而复顾，甚者爪其肤以验其生枯，摇其本以观其疏密，而木之性日以离矣。虽曰爱之，其实害之；虽曰忧之，其实仇之，故不我若也。吾又何能为哉！"],"translation":"郭橐驼，不知道他起初叫什么名字。","annotations":["顺木之天以致其性：顺应事物天性自然规律。"],"sortOrder":12,"totalSegments":6,"totalCards":6},{"id":"art_xb3_13","moduleId":"MODULE_XB_3","title":"石钟山记","subtitle":null,"author":"苏轼","dynasty":"宋代","genre":"散文","isGaoKao72":true,"recitationScope":"第2、3段（夜探石钟山与‘事不目见耳闻’的议论）","fullContent":"元丰七年六月丁丑，余自齐安舟焦入临汝，而长子迈将赴饶之德兴尉，送之至湖口，因得观所谓石钟者。寺僧使小童持斧，于乱石间择其一二扣之，硿硿焉，余固笑而不信也。至暮夜月明，独与迈乘小舟，至绝壁下。大石侧立千尺，如猛兽奇鬼，森然欲搏人；而山上栖鹘，闻人声亦惊起，磔磔云霄间；又有若老人欬且笑于山谷中者，或曰此鹳鹤也。余方心动欲还，而大声发于水上，噌岇如钟鼓不绝。舟人大恐。徐而察之，则山下皆石穴罅，不知其浅深，微波入焉，涵澹澎湃而为此也。舟行适临石磎，余借烛而视之，见一石当中流，可坐百人，空中而多窍，与风水相吞吐，有窾坎镗鞳之声，与向噌岇者相应，如乐作焉。因笑谓迈曰：“汝识之乎？噌岇者，周景王之无射也；窾坎镗鞳者，魏庄子之歌钟也。古之人不余欺也！”\n事不目见耳闻，而臆断其有无，可乎？郦元之所见闻，殆与余同，而言之不详；士大夫终不肯以小舟夜泊绝壁之下，故莫能知；而渔工水师虽知而不能言。此世所以不传也。而陋者乃以斧斤考击而求之，自以为得其实。余是以记之，盖叹郦元之简，而笑李渤之陋也。","paragraphs":["元丰七年六月丁丑，余自齐安舟焦入临汝，而长子迈将赴饶之德兴尉，送之至湖口，因得观所谓石钟者。寺僧使小童持斧，于乱石间择其一二扣之，硿硿焉，余固笑而不信也。至暮夜月明，独与迈乘小舟，至绝壁下。大石侧立千尺，如猛兽奇鬼，森然欲搏人；而山上栖鹘，闻人声亦惊起，磔磔云霄间；又有若老人欬且笑于山谷中者，或曰此鹳鹤也。余方心动欲还，而大声发于水上，噌岇如钟鼓不绝。舟人大恐。徐而察之，则山下皆石穴罅，不知其浅深，微波入焉，涵澹澎湃而为此也。舟行适临石磎，余借烛而视之，见一石当中流，可坐百人，空中而多窍，与风水相吞吐，有窾坎镗鞳之声，与向噌岇者相应，如乐作焉。因笑谓迈曰：“汝识之乎？噌岇者，周景王之无射也；窾坎镗鞳者，魏庄子之歌钟也。古之人不余欺也！”","事不目见耳闻，而臆断其有无，可乎？郦元之所见闻，殆与余同，而言之不详；士大夫终不肯以小舟夜泊绝壁之下，故莫能知；而渔工水师虽知而不能言。此世所以不传也。而陋者乃以斧斤考击而求之，自以为得其实。余是以记之，盖叹郦元之简，而笑李渤之陋也。"],"translation":"《水经》说：“鄱阳湖口有座石钟山在这里。”","annotations":["事不目见耳闻而臆断其有无：实事求是，探求真相。"],"sortOrder":13,"totalSegments":6,"totalCards":6},{"id":"art_xb3_recite_01","moduleId":"MODULE_XB_3_RECITE","title":"拟行路难·其四","subtitle":"其四","author":"鲍照","dynasty":"南朝·宋","genre":"诗","isGaoKao72":true,"recitationScope":"FULL_TEXT","fullContent":"泻水置平地，各自东西南北流。人生亦有命，安能行叹复坐愁？酌酒以自宽，举杯断绝歌路难。心非木石岂无感？吞声踯躅不敢言。","paragraphs":["泻水置平地，各自东西南北流。人生亦有命，安能行叹复坐愁？","酌酒以自宽，举杯断绝歌路难。心非木石岂无感？吞声踯躅不敢言。"],"translation":"把水倒在平地上，水会顺着地势各自流向东西南北。","annotations":["心非木石岂无感：人心非木石，怎能没有真切痛感。"],"sortOrder":1,"totalSegments":4,"totalCards":4},{"id":"art_xb3_recite_02","moduleId":"MODULE_XB_3_RECITE","title":"客至","subtitle":null,"author":"杜甫","dynasty":"唐代","genre":"诗","isGaoKao72":true,"recitationScope":"FULL_TEXT","fullContent":"舍南舍北皆春水，但见群鸥日日来。花径不曾缘客扫，蓬门今始为君开。\n盘飧市远无兼味，樽酒家贫只旧醅。肯与邻翁相对饮，隔篱呼取尽余杯。","paragraphs":["花径不曾缘客扫，蓬门今始为君开。","盘飧市远无兼味，樽酒家贫只旧醅。肯与邻翁相对饮，隔篱呼取尽余杯。"],"translation":"草堂南北两面都是春水流淌，只看到成群的海鸥每天飞来。","annotations":["蓬门今始为君开：纯朴热情的待客真情。"],"sortOrder":2,"totalSegments":4,"totalCards":4},{"id":"art_xb3_recite_03","moduleId":"MODULE_XB_3_RECITE","title":"登快阁","subtitle":null,"author":"黄庭坚","dynasty":"宋代","genre":"诗","isGaoKao72":true,"recitationScope":"FULL_TEXT","fullContent":"痴儿了却公家事，快阁东西倚晚晴。落木千山天远大，澄江一道月分明。\n朱弦已为佳人绝，青眼聊因美酒横。万里归船弄长笛，此心吾与白鸥盟。","paragraphs":["落木千山天远大，澄江一道月分明。","朱弦已为佳人绝，青眼聊因美酒横。万里归船弄长笛，此心吾与白鸥盟。"],"translation":"我这痴呆愚鲁之人忙完公家俗务，登上快阁在傍晚晴空下极目四望。","annotations":["落木千山天远大：境界开阔高远的名联。"],"sortOrder":3,"totalSegments":4,"totalCards":4},{"id":"art_xb3_recite_04","moduleId":"MODULE_XB_3_RECITE","title":"临安春雨初霁","subtitle":null,"author":"陆游","dynasty":"宋代","genre":"诗","isGaoKao72":true,"recitationScope":"FULL_TEXT","fullContent":"世味年来薄似纱，谁令骑马客京华。小楼一夜听春雨，深巷明朝卖杏花。\n矮纸斜行闲作草，晴窗细乳戏分茶。素衣莫起风尘叹，犹及清明可到家。","paragraphs":["世味年来薄似纱，谁令骑马客京华。","小楼一夜听春雨，深巷明朝卖杏花。矮纸斜行闲作草，晴窗细乳戏分茶。"],"translation":"近年来人情世态薄得像一层轻纱，谁让我骑马客居在京华都城。","annotations":["小楼一夜听春雨深巷明朝卖杏花：千古流传的清明名联。"],"sortOrder":4,"totalSegments":4,"totalCards":4}];
